import java.security.KeyFactory;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.spec.X509EncodedKeySpec;
import java.security.spec.PKCS8EncodedKeySpec;

import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.SecureRandom;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.Base64;

import javax.crypto.Cipher;

public class LoadKeysFromHex {
    

    /**
     * Client Private Key
     */
    private static final String CLIENT_PRIV_KEY_HEX = "";
    
    /**
     * Client Public Key
     */
    private static final String CLIENT_PUBLIC_KEY_HEX = "";

    /**
     * Server Private Key
     */
    private static final String SERVER_PRIV_KEY_HEX = "";

    /**
     * Server Public Key
     */
    private static final String SERVER_PUBLIC_KEY_HEX = "";
    
    public static void main(String[] args) throws Exception {
        byte[] privateKeyBytes = hexStringToByteArray(CLIENT_PRIV_KEY_HEX);
        byte[] publicKeyBytes  = hexStringToByteArray(CLIENT_PUBLIC_KEY_HEX);

        // Parse private key using KeyFactory + PKCS8EncodedKeySpec
        PKCS8EncodedKeySpec pkcs8KeySpec = new PKCS8EncodedKeySpec(privateKeyBytes);
        KeyFactory keyFactory = KeyFactory.getInstance("RSA"); 
        PrivateKey clientPrivateKey = keyFactory.generatePrivate(pkcs8KeySpec);

        // Parse public key using KeyFactory + X509EncodedKeySpec
        X509EncodedKeySpec x509KeySpec = new X509EncodedKeySpec(publicKeyBytes);
        PublicKey clientPublicKey = keyFactory.generatePublic(x509KeySpec);

        // System.out.println("Private Key Algorithm: " + clientPrivateKey.getAlgorithm() 
        //                    + ", format: " + clientPrivateKey.getFormat());
        // System.out.println("Public  Key Algorithm: " + clientPublicKey.getAlgorithm() 
        //                    + ", format: " + clientPublicKey.getFormat());
        // System.out.println("Private Key: " + clientPrivateKey.getEncoded());
        // System.out.println("Public Key: " + clientPublicKey.getEncoded());


        byte[] randFromServer = generateRandomBytes(16);
        System.out.println("Server generated random data = " + bytesToHex(randFromServer));

        // Encription using Priv Key
        Cipher cipherEnc = Cipher.getInstance("RSA/ECB/PKCS1Padding");
        cipherEnc.init(Cipher.ENCRYPT_MODE, clientPrivateKey);
        byte[] encryptedByClientPriv = cipherEnc.doFinal(randFromServer);
        System.out.println("Client used PRIVATE key to encrypt -> " + bytesToHex(encryptedByClientPriv));

        // Decription using Public Key
        Cipher cipherDec = Cipher.getInstance("RSA/ECB/PKCS1Padding");
        cipherDec.init(Cipher.DECRYPT_MODE, clientPublicKey);
        byte[] decryptedOnServer = cipherDec.doFinal(encryptedByClientPriv);
        System.out.println("Server used CLIENT's PUBLIC key to decrypt -> " + bytesToHex(decryptedOnServer));

        // Verify
        if (Arrays.equals(randFromServer, decryptedOnServer)) {
            System.out.println("Server verification PASSED! Client indeed holds the private key.");
        } else {
            System.out.println("Server verification FAILED!");
        }

        byte[] randFromServer1 = {1, 2, 3, 4, 5};
        byte[] encryptedByServerPriv = {10, 20, 30, 40, 50};

        // use Base64 to encode
        String randFromServerStr = Base64.getEncoder().encodeToString(randFromServer1);
        String encryptedByServerPrivStr = Base64.getEncoder().encodeToString(encryptedByServerPriv);

        String transportationMsg = randFromServerStr + ',' + encryptedByServerPrivStr;
        System.out.println("transportationMsg: " + transportationMsg);

        // decode transportaionMsg
        if (transportationMsg != null) {
            String[] parts = transportationMsg.split(","); 
            byte[] randFromServer2 = Base64.getDecoder().decode(parts[0]);
            byte[] encryptedByServerPriv2 = Base64.getDecoder().decode(parts[1]);

            System.out.println("Received randFromServer: " + java.util.Arrays.toString(randFromServer2));
            System.out.println("Received encryptedByServerPriv: " + java.util.Arrays.toString(encryptedByServerPriv2));
        }


    }
    
    private static byte[] hexStringToByteArray(String s) {
        if ((s.length() % 2) != 0) {
            throw new IllegalArgumentException("Hex string length must be even.");
        }
        int len = s.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) (
                (Character.digit(s.charAt(i), 16) << 4)
                + Character.digit(s.charAt(i+1), 16)
            );
        }
        return data;
    }

    private static byte[] generateRandomBytes(int length) throws NoSuchAlgorithmException {
        SecureRandom random = new SecureRandom(); 
        byte[] bytes = new byte[length];
        random.nextBytes(bytes);
        return bytes;
    }


    private static String bytesToHex(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            sb.append(String.format("%02X", b));
        }
        return sb.toString();
    }
}
